//! Phase 1 axis benchmark: Radon (chosen axis head) vs minAreaRect boundary
//! vote on real rotated invoice fixtures. 2-D Fourier tilt and Hough were
//! also benchmarked and dropped: 38 deg and 66 deg circular MAE respectively,
//! vs Radon's 0.34 deg (see PLAN.md Phase 1).
//!
//! Fixtures are generated by the operator's Python step into
//! `data/bench_pgms/doc{i}_r{angle}.pgm/.ppm` (3 invoices x 18 angles).
//! Run with:
//!   cargo test -p features-core --test orientation_bench -- --ignored --nocapture
//!
//! The test binary is std (integration tests link std), so file I/O is fine
//! even though the library is no_std.

use features_core::{boundary::boundary_features, radon::radon_features};

use std::fs;

fn parse_pgm(bytes: &[u8]) -> Option<(Vec<f64>, usize, usize)> {
    let (raw, w, h) = parse_netpbm(bytes, 1)?;
    Some((raw.iter().map(|&b| b as f64).collect(), w, h))
}

fn parse_ppm(bytes: &[u8]) -> Option<(Vec<u8>, usize, usize)> {
    parse_netpbm(bytes, 3)
}

fn parse_netpbm(bytes: &[u8], channels: usize) -> Option<(Vec<u8>, usize, usize)> {
    let mut it = bytes
        .split(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
        .filter(|s| !s.is_empty());
    let magic = it.next()?;
    let expected = if channels == 1 { b"P5" } else { b"P6" };
    if magic != expected {
        return None;
    }
    // skip comments
    let mut w = 0usize;
    let mut h = 0usize;
    let mut maxval = 0usize;
    let mut got = 0usize;
    for tok in it {
        if tok[0] == b'#' {
            continue;
        }
        let s = std::str::from_utf8(tok).ok()?;
        let v: usize = s.parse().ok()?;
        match got {
            0 => w = v,
            1 => h = v,
            2 => maxval = v,
            _ => break,
        }
        got += 1;
        if got == 3 {
            break;
        }
    }
    if got < 3 || maxval != 255 {
        return None;
    }
    let header_end = find_pixel_start(bytes);
    let data = &bytes[header_end..];
    let n = w * h * channels;
    if data.len() < n {
        return None;
    }
    Some((data[..n].to_vec(), w, h))
}

fn find_pixel_start(bytes: &[u8]) -> usize {
    // pixel data starts after the maxval field and a single whitespace byte
    let mut i = 0usize;
    let mut fields = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'#' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
            }
            continue;
        }
        if bytes[i].is_ascii_whitespace() {
            // a whitespace run separates fields (but the header also allows
            // multiple); field boundary logic below handles it
            i += 1;
            continue;
        }
        let start = i;
        while i < bytes.len() && !bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        fields += 1;
        if fields == 4 {
            // fields: P5, w, h, maxval; pixel data starts after the ws that
            // ended maxval
            return i;
        }
        let _ = start;
    }
    bytes.len()
}

fn circular_err_deg(a: f64, b: f64) -> f64 {
    let d = (a - b).abs();
    d.min(180.0 - d)
}

#[test]
#[ignore]
fn orientation_benchmark_real_invoices() {
    let base = concat!(env!("CARGO_MANIFEST_DIR"), "/../../data/bench_pgms");
    let n_docs = 3usize;
    let angles: Vec<usize> = (0..180).step_by(10).collect();

    let mut mae = [0.0f64; 2];
    let mut n = [0usize; 2];
    let mut n_boundary_visible = 0usize;

    for doc in 0..n_docs {
        for &a in &angles {
            let pgm = fs::read(format!("{base}/doc{doc}_r{a:03}.pgm")).unwrap();
            let ppm = fs::read(format!("{base}/doc{doc}_r{a:03}.ppm")).unwrap();
            let (gray_bytes, w, h) = parse_pgm(&pgm).unwrap();
            let gray: Vec<f64> = gray_bytes.iter().map(|&b| b as f64).collect();
            let (rgb, _w2, _h2) = parse_ppm(&ppm).unwrap();
            // PIL rotates CCW by `a`; in image coords (y down) that is a
            // rotation of -a, so the text-line axis (mod 180) is 180 - a.
            let gt = ((180 - a) % 180) as f64;

            let radon = radon_features(&gray, w, h)[0].to_degrees();
            let e = circular_err_deg(radon, gt);
            mae[0] += e;
            n[0] += 1;

            let bound = boundary_features(&rgb, w, h);
            let boundary_visible = bound[3];
            if boundary_visible > 0.5 {
                n_boundary_visible += 1;
                let e = circular_err_deg(bound[0].to_degrees(), gt);
                mae[1] += e;
                n[1] += 1;
            }
        }
    }

    let names = ["radon", "minAreaRect"];
    println!(
        "\n=== Phase 1 axis benchmark: real invoices, {n_docs} docs x {} angles ===",
        angles.len()
    );
    for i in 0..2 {
        if n[i] > 0 {
            println!(
                "{:>12}: circular MAE = {:.3} deg over {} samples",
                names[i],
                mae[i] / n[i] as f64,
                n[i]
            );
        } else {
            println!("{:>12}: no samples", names[i]);
        }
    }
    println!(
        "minAreaRect boundary visible on {n_boundary_visible}/{} fixtures",
        n_docs * angles.len()
    );

    // Radon must clear the strict-axis bar on this clean fixture set.
    assert!((mae[0] / (n[0] as f64)) < 3.0, "radon MAE too high");
}
